    0 <= C < 256 -> rw_cells asegs m Dst [CB (Z.to_nat N) junk] -> 0 <= N <= 2^40 -> 0 <= Dst ->
    accessible m Dst N -> shvis m Dst (Dst + N) -> in_app_mem Dst (Dst + N) -> aconst_ok (Dst, Dst + N) ->
